function updateWorkArea(){const top=$('.modes').getBoundingClientRect().bottom+18,bottom=$('#dock').getBoundingClientRect().top-18,offset=innerHeight/2-(top+bottom)/2;camera.setViewOffset(innerWidth,innerHeight,0,offset,innerWidth,innerHeight);camera.updateProjectionMatrix();}
