function pixelScale(position,pixels){return Math.max(.002,camera.position.distanceTo(position)*2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2))*pixels/innerHeight);}
function updateSelection(){const m=meshes.get(selected);outline.visible=!!m&&(mode!=='paint');cornerGroup.visible=!!m&&mode==='build'&&tool==='move'&&!cameraMode;if(m){outline.position.copy(m.position);outline.quaternion.copy(m.quaternion);outline.scale.copy(m.scale).multiplyScalar(1.003);if(cornerGroup.visible){for(const c of corners){c.position.copy(vec(c.userData.sign).multiply(m.scale).multiplyScalar(.5).applyQuaternion(m.quaternion).add(m.position));c.scale.setScalar(pixelScale(c.position,5));}}}}
