const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const reg=t=>{try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};reg({name:'read_cube_model',description:'Read the current cube model and keyframe count.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({mode,boxes:clone(state.boxes),animations:clone(state.animations),animation:state.animation,keyframes:frames().map(f=>f.time),poses:clone(frames()),selected,textureSize:SIZE,textureDensity:activeLayout.density,atlasLayout:clone(activeLayout),gridSize:state.gridSize,textureView,autosave:{pending:autosave.dirty,failed:autosave.failed},livePose:currentPose(),mirrors:clone(mirrors),axisGuide:axisGuide.visible?{joint:axisGuideJoint,axes:[...axisLines].filter(([,line])=>line.visible).map(([name])=>name)}:null})});reg({name:'set_editor_mode',description:'Switch the visible editor mode.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['build','paint','animate']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!['build','paint','animate'].includes(input.mode))throw Error('Unknown editor mode');setMode(input.mode);return {mode};}});reg({name:'undo_cube_edit',description:'Undo the last cube, paint, or animation edit.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{if(!history.length)throw Error('Nothing to undo');historyStep();return {cubes:state.boxes.length,keyframes:frames().length};}});addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

function paintAtlasAt(x,y){if(x<0||y<0||x>=SIZE||y>=SIZE)return;const entry=Object.entries(activeLayout.faces).find(([,r])=>x>=r.x&&x<r.x+r.spanW&&y>=r.y&&y<r.y+r.spanH);if(!entry)return;const n=+entry[0],slot=Math.floor(n/6),face=n%6,b=state.boxes.find(b=>b.slot===slot);if(!b)return;const m=meshes.get(b.id),uv=new THREE.Vector2(x/SIZE,1-y/SIZE),g=m.geometry,i=face*4,uvs=g.attributes.uv,positions=g.attributes.position,u0=uvs.getX(i),v0=uvs.getY(i),du1=uvs.getX(i+1)-u0,dv1=uvs.getY(i+1)-v0,du2=uvs.getX(i+2)-u0,dv2=uvs.getY(i+2)-v0,det=du1*dv2-du2*dv1,a=((uv.x-u0)*dv2-(uv.y-v0)*du2)/det,c=(du1*(uv.y-v0)-dv1*(uv.x-u0))/det,p0=new THREE.Vector3().fromBufferAttribute(positions,i),point=p0.clone().addScaledVector(new THREE.Vector3().fromBufferAttribute(positions,i+1).sub(p0),a).addScaledVector(new THREE.Vector3().fromBufferAttribute(positions,i+2).sub(p0),c);m.updateMatrixWorld();paintSurface({object:m,uv,point:m.localToWorld(point),faceIndex:face*2,face:{normal:new THREE.Vector3().fromBufferAttribute(g.attributes.normal,i)}});}
